const body = $input.first().json.body || $input.first().json;
const message = body.message || body.channel_post || {};
const from = message.from || {};
const chat = message.chat || {};

if (!message.text && !message.voice) {
  return [{ json: { ignore: true, reason: 'No text or voice message' } }];
}

return [{
  json: {
    ignore: false,
    telegram_id: String(from.id || chat.id),
    chat_id: String(chat.id),
    first_name: from.first_name || '',
    last_name: from.last_name || '',
    username: from.username || '',
    text: (message.text || '').trim(),
    message_id: String(message.message_id),
    date: message.date,
    is_voice: !!message.voice
  }
}];

const raw = $input.first().json;
const body = raw.body || raw;
return [{
  json: {
    chat_id: String(body.chat_id || body.telegram_id),
    telegram_id: String(body.telegram_id || body.chat_id),
    first_name: body.first_name || '',
    last_name: body.last_name || '',
    text: (body.text || '').trim()
  }
}];

const outputText = $input.first().json.output || '';
const chatId = $('Normalizar Processor Input').first().json.chat_id;

// Dividir por doble salto de línea en burbujas separadas
const bubbles = outputText
  .split(/\n\n+/)
  .map(s => s.trim())
  .filter(Boolean);

const messages = bubbles.length > 0 ? bubbles : [outputText.trim()];

return [{
  json: {
    chat_id: chatId,
    messages: messages
  }
}];
